// Package httpapi serves the public HTTP API described by api/openapi.
//
// api.gen.go is generated by oapi-codegen from the bundled spec; the rest of
// the package implements the generated StrictServerInterface. Handlers only
// decode, call services and encode. Every error leaves as an RFC 9457
// problem (application/problem+json) carrying a request ID.
package httpapi

import (
	"io"
	"log/slog"
	"net/http"
	"net/url"
	"strings"
	"time"

	"github.com/niltavi/lerryn/server/internal/auth"
)

const (
	// APIVersion is the major version in the path prefix /api/<version>.
	APIVersion = "v1"
	// SpecVersion is info.version of the OpenAPI document this package was
	// generated from. TestSpecVersionMatchesBundle keeps the two in step.
	SpecVersion = "0.9.0"

	// BasePath is the prefix every public API route lives under.
	BasePath = "/api/" + APIVersion + "/"
)

// Options configures the API handler.
type Options struct {
	// PublicURL is the externally reachable base URL of the deployment
	// (server.public_url). Console links in responses are built from it.
	PublicURL string
	// ExtraOrigins are other origins the console is opened at
	// (server.extra_origins). Session writes from them are accepted, and
	// discover's console link follows the one a request came in at.
	ExtraOrigins []string
	// Version, Commit and BuildDate describe the running build, as stamped
	// into the buildinfo package. BuildDate is RFC 3339 or anything else
	// when unknown.
	Version   string
	Commit    string
	BuildDate string
	// Capabilities are the deployment facts that discover reports.
	Capabilities Capabilities
	// Accounts authenticates requests and serves the account operations.
	// Without it every request is anonymous and account operations fail.
	Accounts Accounts
	// Tasks and Runs serve the task and run operations, which fail
	// without them.
	Tasks Tasks
	Runs  Runs
	// RunnerAdmin serves the runner administration operations, which
	// fail without it.
	RunnerAdmin RunnerAdmin
	// Notifications serves the notification channel operations, which
	// fail without it.
	Notifications Notifications
	// Projects, Admin and Audit serve the project, account administration
	// and audit operations. With Audit set, every mutating call that its
	// service did not audit gets a generic audit record.
	Projects Projects
	Admin    Admin
	Audit    Audit
	// Triggers serves the trigger operations and webhook calls.
	Triggers Triggers
	// Credentials serves the credential operations, which fail without it.
	Credentials Credentials
	// Idempotency remembers responses to Idempotency-Key requests. Without
	// it the header is accepted and ignored.
	Idempotency Idempotency
	// StreamsDone, when closed, ends open event streams so a graceful
	// shutdown does not wait for them.
	StreamsDone <-chan struct{}
	// Logger receives errors that are hidden from clients behind
	// internal_error. Nil discards them.
	Logger *slog.Logger
	// TrustedProxies decides whether X-Forwarded-For names the client of a
	// request (server.trusted_proxies). The zero value trusts no proxy.
	TrustedProxies auth.TrustedProxies
}

// New returns the handler for every route under BasePath. Paths under
// BasePath that the spec does not define answer with a not_found problem.
func New(opts Options) http.Handler {
	h, mux := newHandler(opts)
	// More specific patterns registered above win; everything else under
	// the prefix, including a known path with an undeclared method, ends here.
	mux.HandleFunc(BasePath, h.notFound)
	return withRequestID(h.authenticate(h.calls(h.validate(h.idempotent(mux)))))
}

// NewHooks returns the handler for POST /hooks/{triggerId}, the webhook
// calls of external systems (tech design 8.3). Mount it next to New's
// handler, not under it: those calls carry a trigger token, which the
// API's authentication refuses, and no user principal. The trigger
// service checks the token. Requests for any other path are answered
// with not_found.
func NewHooks(opts Options) http.Handler {
	h, mux := newHandler(opts)
	return withRequestID(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost || !strings.HasPrefix(r.URL.Path, hooksPath) {
			h.notFound(w, r)
			return
		}
		ctx := auth.WithClient(r.Context(), h.proxies.Client(r))
		mux.ServeHTTP(w, r.WithContext(withHookToken(ctx, hookToken(r))))
	}))
}

// newHandler builds the handler and the mux with every contract route.
func newHandler(opts Options) (*handler, *http.ServeMux) {
	if opts.Logger == nil {
		opts.Logger = slog.New(slog.NewTextHandler(io.Discard, nil))
	}
	h := &handler{
		log:       opts.Logger,
		publicURL: strings.TrimRight(opts.PublicURL, "/"),
		origins:   consoleOrigins(opts.PublicURL, opts.ExtraOrigins),
		server: ServerInfo{
			Version:   opts.Version,
			Commit:    opts.Commit,
			BuildDate: parseBuildDate(opts.BuildDate),
		},
		capabilities:  opts.Capabilities,
		accounts:      opts.Accounts,
		tasks:         opts.Tasks,
		runnerAdmin:   opts.RunnerAdmin,
		runs:          opts.Runs,
		notifications: opts.Notifications,
		projects:      opts.Projects,
		admin:         opts.Admin,
		audit:         opts.Audit,
		triggers:      opts.Triggers,
		credentials:   opts.Credentials,
		idempotency:   opts.Idempotency,
		streamsDone:   opts.StreamsDone,
		secureCookies: strings.HasPrefix(strings.ToLower(opts.PublicURL), "https://"),
		proxies:       opts.TrustedProxies,
	}

	mux := http.NewServeMux()
	strict := NewStrictHandlerWithOptions(h, []StrictMiddlewareFunc{h.requireAccess, withOIDCState}, StrictHTTPServerOptions{
		RequestErrorHandlerFunc:  h.requestError,
		ResponseErrorHandlerFunc: h.responseError,
	})
	HandlerWithOptions(strict, StdHTTPServerOptions{
		BaseRouter:       mux,
		ErrorHandlerFunc: h.parameterError,
	})
	return h, mux
}

// handler implements StrictServerInterface.
type handler struct {
	log       *slog.Logger
	publicURL string
	// origins are the console's origins: public_url's first, then the
	// extra ones.
	origins      []*url.URL
	server       ServerInfo
	capabilities Capabilities
	accounts     Accounts
	tasks        Tasks
	runs         Runs
	runnerAdmin  RunnerAdmin
	// notifications serves the notification channel operations.
	notifications Notifications
	projects      Projects
	admin         Admin
	audit         Audit
	triggers      Triggers
	credentials   Credentials
	idempotency   Idempotency
	streamsDone   <-chan struct{}
	// secureCookies marks the OIDC state cookie Secure when public_url is
	// https; the session cookie follows the request's address instead.
	secureCookies bool
	// proxies resolves the client address behind reverse proxies.
	proxies auth.TrustedProxies
}

var _ StrictServerInterface = (*handler)(nil)

// consoleLink returns the absolute console URL for path, which must start
// with a slash.
func (h *handler) consoleLink(path string) string {
	return h.publicURL + path
}

// consoleOrigins parses public and the extra origins, dropping any that
// do not parse; config validation has already refused those.
func consoleOrigins(public string, extra []string) []*url.URL {
	var out []*url.URL
	for _, s := range append([]string{public}, extra...) {
		u, err := url.Parse(strings.TrimRight(s, "/"))
		if err != nil || u.Host == "" {
			continue
		}
		out = append(out, &url.URL{Scheme: strings.ToLower(u.Scheme), Host: strings.ToLower(u.Host)})
	}
	return out
}

func parseBuildDate(s string) *time.Time {
	t, err := time.Parse(time.RFC3339, s)
	if err != nil {
		return nil
	}
	t = t.UTC()
	return &t
}
